<?php require dirname(__DIR__).'/src/bootstrap.php'; use DockerManger\Docker;use DockerManger\Compose;$d=new Docker();$c=new Compose(getenv('STACKS_DIR')?:'/VMs/docker');$cs=$d->containers();$ss=$c->stacks();?><!doctype html><html><head><meta charset=utf-8><meta name=viewport content="width=device-width"><title>DockerManger</title><link rel=stylesheet href=/css/app.css></head><body><header><b>DockerManger</b><span>READ ONLY</span></header><main><h1>Docker Host</h1><section><article>Docker <strong><?=htmlspecialchars($d->version())?></strong></article><article>Containers <strong><?=count($cs)?></strong></article><article>Stacks <strong><?=count($ss)?></strong></article></section><h2>Stacks</h2><?php foreach($ss as $s):?><div class=row><?=htmlspecialchars($s['name'])?> <small><?=htmlspecialchars($s['file'])?></small></div><?php endforeach;?></main></body></html>